documents.https://example.org/wot/av/vocabulary/v0:
@prefix av: <https://example.org/wot/av#> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix prov: <http://www.w3.org/ns/prov#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix td: <https://www.w3.org/2019/wot/td#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

av:Assignment a rdfs:Class ;
    rdfs:label "Assignment"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "An immutable accepted mapping of one Need revision to selected input/track paths and initial grants. Not a WoT protocol binding or an execution Activity."@en ;
    rdfs:subClassOf prov:Entity .

av:AssignmentStatus a rdfs:Class ;
    rdfs:label "AssignmentStatus"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "An immutable observation of an Assignment at a generation and observer-incarnation sequence. Currentness, revocation and head selection must be checked externally."@en ;
    rdfs:subClassOf prov:Entity .

av:ChoiceConstraint a rdfs:Class ;
    rdfs:label "Choice constraint"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Membership in a nonempty set of explicitly supported term/resource IRIs for one supported field. Not a general expression language."@en .

av:Condition a rdfs:Class ;
    rdfs:label "Condition"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "One scoped evidence claim, whose four-valued truth state is independent of lifecycle state and digest literals."@en .

av:Connector a rdfs:Class ;
    rdfs:label "Connector"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "A Thing exposing acquisition or adaptation, including host-local native camera access. Not automatically a sensor or PROV Agent."@en ;
    rdfs:subClassOf td:Thing .

av:Controller a rdfs:Class ;
    rdfs:label "Controller"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "A Thing exposing coordination interactions through native TD affordances. Its metadata does not implement admission or authority."@en ;
    rdfs:subClassOf td:Thing .

av:DocumentPin a rdfs:Class ;
    rdfs:label "DocumentPin"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "A fixed representation snapshot with retrieval location, exact-octet SHA-256 and provenance scope. dcterms:format/conformsTo describe the pinned content, not the JSON serialization of this descriptive pin record."@en ;
    rdfs:subClassOf prov:Entity .

av:Fault a rdfs:Class ;
    rdfs:label "Fault"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "A structured failure with a stable code, non-secret explanation, and optional pinned/identified evidence. Retry and uncertain-effect rules are supplied by the control profile."@en .

av:FormReference a rdfs:Class ;
    rdfs:label "FormReference"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "An accepted selection of one native Form and one standard TD operation in one pinned TD. An optional JSON Pointer is an explicit selector against those original JSON bytes, never an assumed URI-fragment service."@en .

av:InferenceModel a rdfs:Class ;
    rdfs:label "InferenceModel"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/provenance> ;
    rdfs:comment "A versioned learned-model manifest with verified files, exact tensor/pre/postprocessing/runtime semantics. Neither a WoT Thing Model, JSON Schema, nor xRegistry model."@en ;
    rdfs:subClassOf prov:Entity .

av:InputAlternative a rdfs:Class ;
    rdfs:label "InputAlternative"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "One complete permitted input contract. Its predicates are conjunctive; alternatives are disjunctive, without array-order priority."@en .

av:InputGroup a rdfs:Class ;
    rdfs:label "InputGroup"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "An all-or-none group of at least two Need inputs, optionally synchronized. Groups are disjoint in v0.1; admission atomicity is not physical transaction atomicity."@en .

av:InputRequirement a rdfs:Class ;
    rdfs:label "Input requirement"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "One named logical workload input, required or optional, with complete alternatives. A Need may have multiple such inputs."@en .

av:InputSelection a rdfs:Class ;
    rdfs:label "InputSelection"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "One accepted logical input, complete alternative, Offer, Mode, adapter configuration and source/sink native Form selections."@en .

av:IntegerConstraint a rdfs:Class ;
    rdfs:label "Integer constraint"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Inclusive integer bounds on one supported integer field. At least one bound is present; identical bounds express exact equality."@en .

av:LeaseGrant a rdfs:Class ;
    rdfs:label "LeaseGrant"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "An immutable revision of an externally enforced, single-authority/scope grant. dcterms:isVersionOf is its series; renewal sequence and fencing epoch are distinct."@en ;
    rdfs:subClassOf prov:Entity .

av:MediaAsset a rdfs:Class ;
    rdfs:label "MediaAsset"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/provenance> ;
    rdfs:comment "Sealed retained still or clip content, complete or explicitly partial, described by an exact typed manifest. Not its Offer or storage endpoint."@en ;
    rdfs:subClassOf prov:Entity .

av:MediaSample a rdfs:Class ;
    rdfs:label "MediaSample"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/provenance> ;
    rdfs:comment "A selected media unit: either derived from a retained asset with a selector, or identified by source, stream incarnation, Track and media-unit sequence. It need not have a media URL."@en ;
    rdfs:subClassOf prov:Entity .

av:MediaSource a rdfs:Class ;
    rdfs:label "MediaSource"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "A physical or logical origin of media, represented as a Thing. Not its media URL or retained content."@en ;
    rdfs:subClassOf td:Thing .

av:Mode a rdfs:Class ;
    rdfs:label "Mode"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "One jointly valid acquisition, native Form, representation, simultaneous track and resource configuration. Track enumeration is complete for this Mode."@en .

av:Need a rdfs:Class ;
    rdfs:label "Need"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "An immutable desired-intent revision. dcterms:isVersionOf identifies its logical Need and generation orders revisions; current heads are external."@en ;
    rdfs:subClassOf prov:Entity .

av:Offer a rdfs:Class ;
    rdfs:label "Offer"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "A discoverable set of mutually alternative complete Modes from one source, not an endpoint or promise of current availability."@en .

av:Preference a rdfs:Class ;
    rdfs:label "Preference"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "One Boolean preference goal for an input. Need preference order gives lexicographic ranking after all hard constraints pass."@en .

av:ProcessingRun a rdfs:Class ;
    rdfs:label "ProcessingRun"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/provenance> ;
    rdfs:comment "An actual capture, transform, training/export, inference or indexing execution. Use PROV directly for inputs, generation, derivation, responsible agents and execution times."@en ;
    rdfs:subClassOf prov:Activity .

av:Processor a rdfs:Class ;
    rdfs:label "Processor"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "A Thing offering media processing or receiving input media. Its service identity is distinct from a running holder incarnation."@en ;
    rdfs:subClassOf td:Thing .

av:QueuePolicy a rdfs:Class ;
    rdfs:label "QueuePolicy"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "A bounded hard policy at one explicitly named processing stage, including overflow and coverage obligations."@en .

av:Rational a rdfs:Class ;
    rdfs:label "Rational"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "An exact reduced numerator/positive-denominator ratio. Units are determined only by the containing predicate."@en .

av:RationalConstraint a rdfs:Class ;
    rdfs:label "Rational constraint"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Inclusive exact-rational bounds on a supported rate field. Compare by cross multiplication, never floating-point rounding."@en .

av:ResourceUse a rdfs:Class ;
    rdfs:label "ResourceUse"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Use of one shared acquisition/configuration resource in a complete state, with an explicit sharing rule."@en .

av:Result a rdfs:Class ;
    rdfs:label "Result"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/provenance> ;
    rdfs:comment "An identified output payload under an accepted ResultContract, with explicit completion state, derivation and durable commitment evidence. Its payload is not forced into a universal detection schema."@en ;
    rdfs:subClassOf prov:Entity .

av:ResultContract a rdfs:Class ;
    rdfs:label "ResultContract"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/provenance> ;
    rdfs:comment "A versioned typed contract for a declared output, naming payload schema/dialect/location, meaning, completion rules and native delivery FormReferences in its pinned manifest."@en ;
    rdfs:subClassOf prov:Entity .

av:TimeSelector a rdfs:Class ;
    rdfs:label "TimeSelector"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "An instant or half-open interval in one named media timeline, in exact rational seconds. Also describes the full finite extent of an offered Clip."@en .

av:Timestamp a rdfs:Class ;
    rdfs:label "Timestamp"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "An observed instant in rational seconds from one incarnation-specific clock origin, with basis, provenance and optional known uncertainty."@en .

av:TimestampMapping a rdfs:Class ;
    rdfs:label "TimestampMapping"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "A declared mapping capability or actual qualified clock mapping, with time basis, seconds-per-tick and a pinned bounded affine-record profile. It is not itself measured exposure evidence."@en .

av:TimingConstraint a rdfs:Class ;
    rdfs:label "Timing constraint"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "A maximum age or pairwise skew in milliseconds for a stated time basis. An age also states the evaluation stage."@en .

av:Track a rdfs:Class ;
    rdfs:label "Track"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "One named simultaneous media component of a Mode, with one encoded or raw wire representation. Identity is not an SSRC or device index."@en .

av:TrackRequirement a rdfs:Class ;
    rdfs:label "Track requirement"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "One logical required or optional track at the wire or delivered boundary. Equal dcterms:identifier values join its wire and delivered contracts within an alternative."@en .

av:TrackSelection a rdfs:Class ;
    rdfs:label "TrackSelection"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "A mapping of one offered Track to the wire and/or delivered TrackRequirements of one logical track; the qualified adapter configuration supplies the actual boundary signatures."@en .

av: a owl:Ontology ;
    dcterms:created "2026-09-14"^^xsd:date ;
    dcterms:description "Original proposal. Namespace is unregistered and context URL is unhosted. No deployment, protocol implementation, or certification is asserted."@en ;
    dcterms:references <https://www.dublincore.org/specifications/dublin-core/dcmi-terms/2020-01-20/>,
        <https://www.w3.org/TR/2013/REC-prov-o-20130430/>,
        <https://www.w3.org/TR/2020/REC-json-ld11-20200716/>,
        <https://www.w3.org/TR/2023/REC-wot-thing-description11-20231205/> ;
    dcterms:title "Proposed WoT AV vocabulary v0.1"@en ;
    owl:versionInfo "0.1-proposed" .

av:AAC a rdfs:Resource ;
    rdfs:label "AAC"@en ;
    rdfs:comment "AAC family; object type/configuration is required by the pinned decoder configuration."@en .

av:Accepted a rdfs:Resource ;
    rdfs:label "Accepted"@en ;
    rdfs:comment "Admission succeeded, not readiness."@en .

av:Active a rdfs:Resource ;
    rdfs:label "Active"@en ;
    rdfs:comment "Desired intent is active, subject to its authoritative current head."@en .

av:AgeBudgetUnproven a rdfs:Resource ;
    rdfs:label "AgeBudgetUnproven"@en ;
    rdfs:comment "The worst-case age budget cannot be proved."@en .

av:ApplicationIngress a rdfs:Resource ;
    rdfs:label "ApplicationIngress"@en ;
    rdfs:comment "The application receipt boundary for age evaluation."@en .

av:ApplicationReady a rdfs:Resource ;
    rdfs:label "ApplicationReady"@en ;
    rdfs:comment "All required delivered-media predicates have been qualified."@en .

av:Applying a rdfs:Resource ;
    rdfs:label "Applying"@en ;
    rdfs:comment "Applying the accepted configuration/plan."@en .

av:ArtifactFile a rdfs:Resource ;
    rdfs:label "ArtifactFile"@en ;
    rdfs:comment "A complete artifact file representation, after HTTP content decoding but before media decoding."@en .

av:AtInstant a rdfs:Resource ;
    rdfs:label "AtInstant"@en ;
    rdfs:comment "One timestamp-selected sample according to the pinned selector profile; end is absent."@en .

av:BGR8 a rdfs:Resource ;
    rdfs:label "BGR8"@en ;
    rdfs:comment "uint8 B,G,R component order; HWC logical geometry; three bytes per pixel."@en .

av:BackendTrackUnsupported a rdfs:Resource ;
    rdfs:label "BackendTrackUnsupported"@en ;
    rdfs:comment "The chosen adapter cannot deliver the required track."@en .

av:BestEffort a rdfs:Resource ;
    rdfs:label "BestEffort"@en ;
    rdfs:comment "Declared drops may occur; no completeness guarantee."@en .

av:BlockUpstream a rdfs:Resource ;
    rdfs:label "BlockUpstream"@en ;
    rdfs:comment "Backpressure only where a qualified upstream can pause or bounded spool proves feasibility."@en .

av:Bundle a rdfs:Resource ;
    rdfs:label "Bundle"@en ;
    rdfs:comment "One synchronized group of video units and associated audio blocks."@en .

av:Byte a rdfs:Resource ;
    rdfs:label "Byte"@en ;
    rdfs:comment "One octet of buffered content."@en .

av:Canceled a rdfs:Resource ;
    rdfs:label "Canceled"@en ;
    rdfs:comment "Execution was canceled."@en .

av:CapacityExceeded a rdfs:Resource ;
    rdfs:label "CapacityExceeded"@en ;
    rdfs:comment "Qualified bounded capacity is insufficient."@en .

av:CaptureAuthorityRequired a rdfs:Resource ;
    rdfs:label "CaptureAuthorityRequired"@en ;
    rdfs:comment "Acquisition/configuration authority is not established."@en .

av:CaptureIngress a rdfs:Resource ;
    rdfs:label "CaptureIngress"@en ;
    rdfs:comment "First captured/acquired units before branch selection."@en .

av:CaptureTime a rdfs:Resource ;
    rdfs:label "CaptureTime"@en ;
    rdfs:comment "Video exposure midpoint, or first audio sample time, when qualified as such."@en .

av:Clip a rdfs:Resource ;
    rdfs:label "Clip"@en ;
    rdfs:comment "Finite media with a named timeline and full offered extent."@en .

av:ClockUncertain a rdfs:Resource ;
    rdfs:label "ClockUncertain"@en ;
    rdfs:comment "Clock uncertainty prevents a currentness/validity decision."@en .

av:ClockUnqualified a rdfs:Resource ;
    rdfs:label "ClockUnqualified"@en ;
    rdfs:comment "The required time basis or common-clock mapping is unqualified."@en .

av:ColorConvert a rdfs:Resource ;
    rdfs:label "ColorConvert"@en ;
    rdfs:comment "Convert pixel/channel color representation, with qualified colorimetry."@en .

av:CommitTime a rdfs:Resource ;
    rdfs:label "CommitTime"@en ;
    rdfs:comment "Durable result-commit time, not capture time."@en .

av:Complete a rdfs:Resource ;
    rdfs:label "Complete"@en ;
    rdfs:comment "The declared content/coverage obligation is complete, including a valid empty detection set."@en .

av:ConfigureAndCapture a rdfs:Resource ;
    rdfs:label "ConfigureAndCapture"@en ;
    rdfs:comment "The selected plan needs explicit authority for both the exact configuration and acquisition."@en .

av:Constant a rdfs:Resource ;
    rdfs:label "Constant"@en ;
    rdfs:comment "Exact constant media cadence, requiring frameRate."@en .

av:ContextDocument a rdfs:Resource ;
    rdfs:label "ContextDocument"@en ;
    rdfs:comment "A JSON-LD context representation used for semantic interpretation."@en .

av:Contiguous a rdfs:Resource ;
    rdfs:label "Contiguous"@en ;
    rdfs:comment "No inter-row gaps for packed raw images; detailed plane layout remains fixed by pixel format."@en .

av:ContractMismatch a rdfs:Resource ;
    rdfs:label "ContractMismatch"@en ;
    rdfs:comment "Output, model or negotiated media violates the accepted contract."@en .

av:CoveringInterval a rdfs:Resource ;
    rdfs:label "CoveringInterval"@en ;
    rdfs:comment "May include at most toleranceMs extra media at either edge; no internal omission is authorized."@en .

av:Decode a rdfs:Resource ;
    rdfs:label "Decode"@en ;
    rdfs:comment "Decode an encoded representation."@en .

av:DecodedDelivery a rdfs:Resource ;
    rdfs:label "DecodedDelivery"@en ;
    rdfs:comment "Decoded media immediately before application delivery."@en .

av:Degraded a rdfs:Resource ;
    rdfs:label "Degraded"@en ;
    rdfs:comment "One or more current execution obligations are not met."@en .

av:DependencyUnavailable a rdfs:Resource ;
    rdfs:label "DependencyUnavailable"@en ;
    rdfs:comment "An exact pinned dependency cannot be retrieved."@en .

av:DirectorySnapshot a rdfs:Resource ;
    rdfs:label "DirectorySnapshot"@en ;
    rdfs:comment "Exact directory-enriched snapshot, including registration fields and directory-assigned identity."@en .

av:DomainDocument a rdfs:Resource ;
    rdfs:label "DomainDocument"@en ;
    rdfs:comment "A Need, Assignment, status, grant or other domain-record representation."@en .

av:Draining a rdfs:Resource ;
    rdfs:label "Draining"@en ;
    rdfs:comment "Owned work is being withdrawn/cleaned up; not proof of cleanup."@en .

av:DropNewest a rdfs:Resource ;
    rdfs:label "DropNewest"@en ;
    rdfs:comment "Discard the incoming unit at this stage."@en .

av:DropOldest a rdfs:Resource ;
    rdfs:label "DropOldest"@en ;
    rdfs:comment "Discard the oldest queued unit at this stage."@en .

av:DuplicateFrames a rdfs:Resource ;
    rdfs:label "DuplicateFrames"@en ;
    rdfs:comment "Synthesize repeated video frames; cannot be inferred from a rate request."@en .

av:EncodedAudio a rdfs:Resource ;
    rdfs:label "EncodedAudio"@en ;
    rdfs:comment "Codec-encoded audio, distinct from decoded samples."@en .

av:EncodedBranch a rdfs:Resource ;
    rdfs:label "EncodedBranch"@en ;
    rdfs:comment "Encoded-media branch after acquisition."@en .

av:EncodedVideo a rdfs:Resource ;
    rdfs:label "EncodedVideo"@en ;
    rdfs:comment "Codec-encoded video/image data, distinct from decoded pixels."@en .

av:Error a rdfs:Resource ;
    rdfs:label "Error"@en ;
    rdfs:comment "A result reports failure rather than successful empty content."@en .

av:ExactSamples a rdfs:Resource ;
    rdfs:label "ExactSamples"@en ;
    rdfs:comment "Samples whose presentation timestamps lie in [start,end), including audio-sample trimming."@en .

av:Exclusive a rdfs:Resource ;
    rdfs:label "Exclusive"@en ;
    rdfs:comment "No concurrent conflicting allocation in this resource scope."@en .

av:F32LE a rdfs:Resource ;
    rdfs:label "F32LE"@en ;
    rdfs:comment "IEEE 754 binary32 little-endian PCM samples."@en .

av:Fail a rdfs:Resource ;
    rdfs:label "Fail"@en ;
    rdfs:comment "Fail the affected completeness obligation."@en,
        "Report failure rather than silently continue."@en .

av:Failed a rdfs:Resource ;
    rdfs:label "Failed"@en ;
    rdfs:comment "Execution failed."@en,
        "The attempt failed; recovery requires a new Assignment."@en .

av:False a rdfs:Resource ;
    rdfs:label "False"@en ;
    rdfs:comment "Evidence establishes the claim does not hold; not merely absent information."@en .

av:Frame a rdfs:Resource ;
    rdfs:label "Frame"@en ;
    rdfs:comment "One video media unit."@en .

av:FromThing a rdfs:Resource ;
    rdfs:label "FromThing"@en ;
    rdfs:comment "Media leaves the addressed Thing; xRegistry client-relative usage is consumer."@en .

av:H264 a rdfs:Resource ;
    rdfs:label "H264"@en ;
    rdfs:comment "ITU-T H.264/AVC family; profile, level and other decoder parameters require the pinned configuration."@en .

av:HostLocal a rdfs:Resource ;
    rdfs:label "HostLocal"@en ;
    rdfs:comment "Access requires the declared host and native runtime."@en .

av:IdempotencyConflict a rdfs:Resource ;
    rdfs:label "IdempotencyConflict"@en ;
    rdfs:comment "The same scoped client key was reused with different canonical input."@en .

av:InferenceStart a rdfs:Resource ;
    rdfs:label "InferenceStart"@en ;
    rdfs:comment "The beginning of processing/inference for age evaluation."@en .

av:IntegrityMismatch a rdfs:Resource ;
    rdfs:label "IntegrityMismatch"@en ;
    rdfs:comment "Pinned content or immutable identity has conflicting bytes."@en .

av:Interleaved a rdfs:Resource ;
    rdfs:label "Interleaved"@en ;
    rdfs:comment "Audio channel samples alternate within each sample frame."@en .

av:InvalidContract a rdfs:Resource ;
    rdfs:label "InvalidContract"@en ;
    rdfs:comment "Invalid syntax, structure, identifier or conditional contract."@en .

av:JPEG a rdfs:Resource ;
    rdfs:label "JPEG"@en ;
    rdfs:comment "JPEG-coded image data; exact coding variant belongs to the pinned configuration."@en .

av:LeaseExpired a rdfs:Resource ;
    rdfs:label "LeaseExpired"@en ;
    rdfs:comment "The applicable enforced grant expired."@en .

av:LeaseRevoked a rdfs:Resource ;
    rdfs:label "LeaseRevoked"@en ;
    rdfs:comment "The applicable enforced grant was revoked."@en .

av:Live a rdfs:Resource ;
    rdfs:label "Live"@en ;
    rdfs:comment "Unbounded live media; no invented zero duration."@en .

av:ManifestDocument a rdfs:Resource ;
    rdfs:label "ManifestDocument"@en ;
    rdfs:comment "A typed media/model/result-contract manifest."@en .

av:MediaObserved a rdfs:Resource ;
    rdfs:label "MediaObserved"@en ;
    rdfs:comment "Selected media samples have actually been observed."@en .

av:MissingTrack a rdfs:Resource ;
    rdfs:label "MissingTrack"@en ;
    rdfs:comment "A required logical track cannot be selected."@en .

av:ModelInput a rdfs:Resource ;
    rdfs:label "ModelInput"@en ;
    rdfs:comment "Model tensor/input queue."@en .

av:ModelLoaded a rdfs:Resource ;
    rdfs:label "ModelLoaded"@en ;
    rdfs:comment "The exact accepted model/files/execution configuration are loaded by the identified processor incarnation."@en .

av:Mono a rdfs:Resource ;
    rdfs:label "Mono"@en ;
    rdfs:comment "One audio channel."@en .

av:Mono8 a rdfs:Resource ;
    rdfs:label "Mono8"@en ;
    rdfs:comment "One uint8 intensity component per pixel."@en .

av:Network a rdfs:Resource ;
    rdfs:label "Network"@en ;
    rdfs:comment "Access uses a network binding; reachability is still separately proven."@en .

av:NoFeasibleAssignment a rdfs:Resource ;
    rdfs:label "NoFeasibleAssignment"@en ;
    rdfs:comment "No complete accepted mapping is feasible."@en .

av:NoIntentionalDrop a rdfs:Resource ;
    rdfs:label "NoIntentionalDrop"@en ;
    rdfs:comment "No planned discard from the named stage through application delivery; not a promise against sensor/network loss."@en .

av:NoJointMode a rdfs:Resource ;
    rdfs:label "NoJointMode"@en ;
    rdfs:comment "No single jointly supported Mode satisfies the alternative."@en .

av:NotApplicable a rdfs:Resource ;
    rdfs:label "NotApplicable"@en ;
    rdfs:comment "The obligation is explicitly absent; only allowed by the class-specific lifecycle contract."@en .

av:Observe a rdfs:Resource ;
    rdfs:label "Observe"@en ;
    rdfs:comment "No trigger or acquisition-configuration mutation is authorized."@en .

av:OntologyDocument a rdfs:Resource ;
    rdfs:label "OntologyDocument"@en ;
    rdfs:comment "A vocabulary/ontology representation used for interpretation."@en .

av:Optional a rdfs:Resource ;
    rdfs:label "Optional"@en ;
    rdfs:comment "May be explicitly omitted; if admitted, all its constraints remain hard."@en .

av:OutcomeUncertain a rdfs:Resource ;
    rdfs:label "OutcomeUncertain"@en ;
    rdfs:comment "An externally visible effect has an uncertain outcome."@en .

av:PCM a rdfs:Resource ;
    rdfs:label "PCM"@en ;
    rdfs:comment "Uncompressed audio samples with explicit sample and buffer formats."@en .

av:Packet a rdfs:Resource ;
    rdfs:label "Packet"@en ;
    rdfs:comment "One binding-defined encoded packet, not a decoded frame."@en .

av:Partial a rdfs:Resource ;
    rdfs:label "Partial"@en ;
    rdfs:comment "Finalized content is incomplete and has explicit gaps/issues."@en .

av:PayloadDocument a rdfs:Resource ;
    rdfs:label "PayloadDocument"@en ;
    rdfs:comment "A particular result payload representation."@en .

av:Planar a rdfs:Resource ;
    rdfs:label "Planar"@en ;
    rdfs:comment "Each audio channel occupies its own plane."@en .

av:PrerollDecode a rdfs:Resource ;
    rdfs:label "PrerollDecode"@en ;
    rdfs:comment "Decode/discard prerequisite samples before the selected interval."@en .

av:PresentationTime a rdfs:Resource ;
    rdfs:label "PresentationTime"@en ;
    rdfs:comment "Media presentation timestamp semantics, not automatically UTC."@en .

av:ProcessingTime a rdfs:Resource ;
    rdfs:label "ProcessingTime"@en ;
    rdfs:comment "Time at the identified processing boundary."@en .

av:ProfileDocument a rdfs:Resource ;
    rdfs:label "ProfileDocument"@en ;
    rdfs:comment "A recognized versioned operational/configuration profile or specification."@en .

av:PublisherTD a rdfs:Resource ;
    rdfs:label "PublisherTD"@en ;
    rdfs:comment "Exact publisher TD representation; no directory enrichment is silently removed."@en .

av:QueuePolicyConflict a rdfs:Resource ;
    rdfs:label "QueuePolicyConflict"@en ;
    rdfs:comment "Queue, overflow, branch-isolation or coverage constraints conflict."@en .

av:RGB8 a rdfs:Resource ;
    rdfs:label "RGB8"@en ;
    rdfs:comment "uint8 R,G,B component order; HWC logical geometry; three bytes per pixel."@en .

av:RangeUnavailable a rdfs:Resource ;
    rdfs:label "RangeUnavailable"@en ;
    rdfs:comment "The requested finite interval is not available."@en .

av:RawVideo a rdfs:Resource ;
    rdfs:label "RawVideo"@en ;
    rdfs:comment "Unencoded image pixels with a fixed format and memory layout."@en .

av:Ready a rdfs:Resource ;
    rdfs:label "Ready"@en ;
    rdfs:comment "Application-ready is true; required model processing additionally needs model-loaded true."@en .

av:ReceiptDocument a rdfs:Resource ;
    rdfs:label "ReceiptDocument"@en ;
    rdfs:comment "An authenticated durable commitment receipt representation."@en .

av:ReceiptTime a rdfs:Resource ;
    rdfs:label "ReceiptTime"@en ;
    rdfs:comment "Time observed at the identified receiver."@en .

av:ReleaseIncomplete a rdfs:Resource ;
    rdfs:label "ReleaseIncomplete"@en ;
    rdfs:comment "Cleanup of this Assignment's owned scope is not established."@en .

av:Released a rdfs:Resource ;
    rdfs:label "Released"@en ;
    rdfs:comment "Authoritative scoped cleanup is evidenced; terminal for this Assignment."@en .

av:RemixAudio a rdfs:Resource ;
    rdfs:label "RemixAudio"@en ;
    rdfs:comment "Change audio channels/layout."@en .

av:Report a rdfs:Resource ;
    rdfs:label "Report"@en ;
    rdfs:comment "Report incomplete coverage explicitly; not complete success."@en .

av:RequestCapture a rdfs:Resource ;
    rdfs:label "RequestCapture"@en ;
    rdfs:comment "The selected plan needs authority to request acquisition without changing the selected configuration."@en .

av:Required a rdfs:Resource ;
    rdfs:label "Required"@en ;
    rdfs:comment "Must be admitted and satisfied."@en .

av:ResampleAudio a rdfs:Resource ;
    rdfs:label "ResampleAudio"@en ;
    rdfs:comment "Change audio sample rate."@en .

av:ResizeCrop a rdfs:Resource ;
    rdfs:label "ResizeCrop"@en ;
    rdfs:comment "Aspect-preserving resize/crop with a pinned crop rule."@en .

av:ResizeLetterbox a rdfs:Resource ;
    rdfs:label "ResizeLetterbox"@en ;
    rdfs:comment "Aspect-preserving resize/pad with pinned padding, interpolation and rounding."@en .

av:ResizeStretch a rdfs:Resource ;
    rdfs:label "ResizeStretch"@en ;
    rdfs:comment "Resize without aspect preservation; the profile fixes interpolation and rounding."@en .

av:ResultCommitFailed a rdfs:Resource ;
    rdfs:label "ResultCommitFailed"@en ;
    rdfs:comment "Computation/delivery did not produce a valid durable receipt."@en .

av:ResultCommitted a rdfs:Resource ;
    rdfs:label "ResultCommitted"@en ;
    rdfs:comment "At least one output under an accepted contract has an identified durable commitment receipt; not all-work-complete."@en .

av:RevisionConflict a rdfs:Resource ;
    rdfs:label "RevisionConflict"@en ;
    rdfs:comment "The expected logical Need generation/current head differs."@en .

av:Running a rdfs:Resource ;
    rdfs:label "Running"@en ;
    rdfs:comment "Actual execution is in progress."@en .

av:S16LE a rdfs:Resource ;
    rdfs:label "S16LE"@en ;
    rdfs:comment "Signed 16-bit little-endian PCM samples."@en .

av:SameConfiguration a rdfs:Resource ;
    rdfs:label "SameConfiguration"@en ;
    rdfs:comment "Share only when complete configuration pins identify identical configuration content under the same recognized profile."@en .

av:SeekSemanticsUnsupported a rdfs:Resource ;
    rdfs:label "SeekSemanticsUnsupported"@en ;
    rdfs:comment "The selector cannot be implemented with the required boundary semantics."@en .

av:ShapeDocument a rdfs:Resource ;
    rdfs:label "ShapeDocument"@en ;
    rdfs:comment "A shape/schema validation representation."@en .

av:SharedConfigurationConflict a rdfs:Resource ;
    rdfs:label "SharedConfigurationConflict"@en ;
    rdfs:comment "A shared resource has an incompatible complete configuration."@en .

av:SkewBudgetUnproven a rdfs:Resource ;
    rdfs:label "SkewBudgetUnproven"@en ;
    rdfs:comment "The worst-case pairwise skew budget cannot be proved."@en .

av:StaleObservation a rdfs:Resource ;
    rdfs:label "StaleObservation"@en ;
    rdfs:comment "The observation is stale, superseded or belongs to an obsolete incarnation."@en .

av:StereoLR a rdfs:Resource ;
    rdfs:label "StereoLR"@en ;
    rdfs:comment "Two ordered audio channels: left, then right."@en .

av:Still a rdfs:Resource ;
    rdfs:label "Still"@en ;
    rdfs:comment "An image-shaped acquisition/access, not necessarily a new exposure."@en .

av:Strided a rdfs:Resource ;
    rdfs:label "Strided"@en ;
    rdfs:comment "Explicit image plane/row strides are supplied by the qualified configuration."@en .

av:Succeeded a rdfs:Resource ;
    rdfs:label "Succeeded"@en ;
    rdfs:comment "Computation completed successfully, not necessarily result commitment."@en .

av:TemporalSubsample a rdfs:Resource ;
    rdfs:label "TemporalSubsample"@en ;
    rdfs:comment "Intentionally select fewer media samples; not queue overflow."@en .

av:ToThing a rdfs:Resource ;
    rdfs:label "ToThing"@en ;
    rdfs:comment "Media enters the addressed Thing; xRegistry client-relative usage is producer."@en .

av:TransformForbidden a rdfs:Resource ;
    rdfs:label "TransformForbidden"@en ;
    rdfs:comment "The needed operation/preprocessing was not explicitly authorized."@en .

av:Triggered a rdfs:Resource ;
    rdfs:label "Triggered"@en ;
    rdfs:comment "Event/trigger-determined cadence, not a constant rate."@en .

av:True a rdfs:Resource ;
    rdfs:label "True"@en ;
    rdfs:comment "Positive claim supported by identified evidence."@en .

av:Unauthorized a rdfs:Resource ;
    rdfs:label "Unauthorized"@en ;
    rdfs:comment "Required authorization is absent."@en .

av:Uncertain a rdfs:Resource ;
    rdfs:label "Uncertain"@en ;
    rdfs:comment "An effect may have happened; reconcile rather than blindly repeat."@en .

av:Unknown a rdfs:Resource ;
    rdfs:label "Unknown"@en ;
    rdfs:comment "The claim has not been established either way."@en .

av:UnknownRequiredFact a rdfs:Resource ;
    rdfs:label "UnknownRequiredFact"@en ;
    rdfs:comment "Required evidence is unavailable or unknown."@en .

av:UnreachablePlacement a rdfs:Resource ;
    rdfs:label "UnreachablePlacement"@en ;
    rdfs:comment "Host/runtime/reachability constraints fail."@en .

av:UnsupportedProfile a rdfs:Resource ;
    rdfs:label "UnsupportedProfile"@en ;
    rdfs:comment "A required binding, configuration or validation profile is not recognized."@en .

av:Variable a rdfs:Resource ;
    rdfs:label "Variable"@en ;
    rdfs:comment "Variable media cadence; no exact frameRate is implied."@en .

av:Withdrawn a rdfs:Resource ;
    rdfs:label "Withdrawn"@en ;
    rdfs:comment "This immutable revision records withdrawal; no new work is authorized."@en .

av:YUV420P a rdfs:Resource ;
    rdfs:label "YUV420P"@en ;
    rdfs:comment "8-bit planar Y then U then V, 4:2:0 sampling; exact colorimetry and strides require configuration."@en .

av:allowedPreprocessing a rdf:Property ;
    rdfs:label "allowedPreprocessing"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Explicitly permitted exact model-preprocessing profile pins, independent of image delivery transforms. Omission or empty means none permitted; a model declaration does not grant permission. Profile uses (alternative domains, not RDFS intersections): av:Need -> av:DocumentPin [0..*]."@en .

av:allowedValues a rdf:Property ;
    rdfs:label "allowedValues"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Nonempty allowed IRI set for the selected field. Fields with controlled enums restrict values to that enum; host/backend/source/configuration use exact recognized identities/pins. Profile uses (alternative domains, not RDFS intersections): av:ChoiceConstraint -> IRI [1..*]."@en .

av:alternative a rdf:Property ;
    rdfs:label "alternative"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Complete permitted alternatives on a requirement; exactly one chosen alternative on an InputSelection. Profile uses (alternative domains, not RDFS intersections): av:InputRequirement -> av:InputAlternative [1..*]; av:InputSelection -> av:InputAlternative [1..1]."@en .

av:assignment a rdf:Property ;
    rdfs:label "assignment"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Exact immutable accepted attempt whose status or actual processing is described. Profile uses (alternative domains, not RDFS intersections): av:AssignmentStatus -> av:Assignment [1..1]; av:ProcessingRun -> av:Assignment [1..1]."@en .

av:authority a rdf:Property ;
    rdfs:label "authority"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "External grant enforcer identity. Only its current state and per-effect fencing checks confer authority. Profile uses (alternative domains, not RDFS intersections): av:LeaseGrant -> IRI [1..1]."@en .

av:backend a rdf:Property ;
    rdfs:label "backend"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Qualified native/adapter runtime identity with a versioned capability profile. Profile uses (alternative domains, not RDFS intersections): av:Connector -> IRI [1..1]."@en .

av:basis a rdf:Property ;
    rdfs:label "basis"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Physical/semantic meaning of time, independent of clock unit or mapping availability. Profile uses (alternative domains, not RDFS intersections): av:TimestampMapping -> enum:TimeBasis [1..1]; av:Timestamp -> enum:TimeBasis [1..1]; av:TimingConstraint -> ['av:CaptureTime', 'av:PresentationTime', 'av:ReceiptTime'] [1..1]."@en .

av:binding a rdf:Property ;
    rdfs:label "binding"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Recognized binding specification IRI. Its exact content and dependencies must be pinned at acceptance; this is not native Thing profile conformance and does not by itself assert media flow. Optional on generic Forms; required on media Forms under native_form_rules. Profile uses (alternative domains, not RDFS intersections): hctl:Form -> IRI [0..1]."@en .

av:bufferLayout a rdf:Property ;
    rdfs:label "bufferLayout"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Raw-video Contiguous/Strided or PCM Interleaved/Planar memory layout; applicability is representation-specific. Profile uses (alternative domains, not RDFS intersections): av:Track -> enum:BufferLayout [0..1]."@en .

av:cadence a rdf:Property ;
    rdfs:label "cadence"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Offered video cadence semantics. Still omits cadence/frameRate; Constant requires frameRate; Variable/Triggered do not assert an exact rate. Profile uses (alternative domains, not RDFS intersections): av:Track -> enum:Cadence [0..1]."@en .

av:capacity a rdf:Property ;
    rdfs:label "capacity"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Finite positive number of units buffered at the named queue stage; no unbounded sentinel. Profile uses (alternative domains, not RDFS intersections): av:QueuePolicy -> integer [1..1]."@en .

av:captureIntent a rdf:Property ;
    rdfs:label "captureIntent"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Permitted acquisition effect; grants, control Forms, trigger behavior and uncertain outcomes must still be qualified by the pinned acquisition/control profile. Profile uses (alternative domains, not RDFS intersections): av:InputAlternative -> enum:CaptureIntent [1..1]."@en .

av:channelLayout a rdf:Property ;
    rdfs:label "channelLayout"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Audio channel meaning/order, independent of interleaved/planar storage. Profile uses (alternative domains, not RDFS intersections): av:Track -> enum:ChannelLayout [0..1]."@en .

av:channels a rdf:Property ;
    rdfs:label "channels"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Number of audio channels; Mono requires one and StereoLR two. Fixed unit: channel. Profile uses (alternative domains, not RDFS intersections): av:Track -> integer [0..1]."@en .

av:clock a rdf:Property ;
    rdfs:label "clock"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Named clock/timeline origin and incarnation. Matching names, NTP/PTP labels or RTP clocks alone do not prove synchronization. Profile uses (alternative domains, not RDFS intersections): av:TimestampMapping -> IRI [1..1]; av:Timestamp -> IRI [1..1]; av:TimeSelector -> IRI [1..1]; av:AssignmentStatus -> IRI [1..1]; av:LeaseGrant -> IRI [1..1]."@en .

av:code a rdf:Property ;
    rdfs:label "code"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Stable failure IRI from the closed v0.1 failure vocabulary; the control profile fixes action outcomes and retryability. Profile uses (alternative domains, not RDFS intersections): av:Fault -> enum:FaultCode [1..1]."@en .

av:codec a rdf:Property ;
    rdfs:label "codec"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Encoded-media codec family; an SDP/JSON Form content type is not a codec claim. Profile uses (alternative domains, not RDFS intersections): av:Track -> enum:Codec [0..1]."@en .

av:committedAt a rdf:Property ;
    rdfs:label "committedAt"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/provenance> ;
    rdfs:comment "Durable commitment time established by the authenticated receipt, not capture, computation completion, delivery or subscriber acknowledgment. Profile uses (alternative domains, not RDFS intersections): av:Result -> dateTime [1..1]."@en .

av:condition a rdf:Property ;
    rdfs:label "condition"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Which distinct condition is claimed: media observed, application ready, model loaded, or result committed. Profile uses (alternative domains, not RDFS intersections): av:Condition -> enum:ConditionName [1..1]."@en .

av:conditionState a rdf:Property ;
    rdfs:label "conditionState"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Explicit True/False/Unknown/NotApplicable IRI, never JSON false as an unknown sentinel. True requires evidence; false is an actual negative assessment. Profile uses (alternative domains, not RDFS intersections): av:Condition -> enum:TruthState [1..1]."@en .

av:conditions a rdf:Property ;
    rdfs:label "conditions"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Exactly one of each of the four distinct Condition names; cardinality alone does not prove their uniqueness or truth. Profile uses (alternative domains, not RDFS intersections): av:AssignmentStatus -> av:Condition [4..4]."@en .

av:configuration a rdf:Property ;
    rdfs:label "configuration"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "One exact typed configuration pin. Mode: acquisition/capture/control/seek profile; Track: codec/layout details; ResourceUse: complete resource state; TimestampMapping: bounded affine records; InputSelection: qualified adapter plan; ProcessingRun: actual execution configuration. Unsupported profiles cannot establish feasibility. Profile uses (alternative domains, not RDFS intersections): av:Mode -> av:DocumentPin [1..1]; av:Track -> av:DocumentPin [0..1]; av:ResourceUse -> av:DocumentPin [1..1]; av:TimestampMapping -> av:DocumentPin [0..1]; av:InputSelection -> av:DocumentPin [1..1]; av:ProcessingRun -> av:DocumentPin [1..1]."@en .

av:connector a rdf:Property ;
    rdfs:label "connector"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Acquisition/adaptation Thing; required for host-local native-camera sources. Profile uses (alternative domains, not RDFS intersections): av:MediaSource -> av:Connector [0..1]."@en .

av:constraints a rdf:Property ;
    rdfs:label "constraints"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Conjunctive typed predicates. Track fields use supported integer/rational/choice constraints; an alternative permits only source/host/backend placement ChoiceConstraints. Profile uses (alternative domains, not RDFS intersections): av:TrackRequirement -> ['av:IntegerConstraint', 'av:RationalConstraint', 'av:ChoiceConstraint'] [0..*]; av:InputAlternative -> av:ChoiceConstraint [0..*]."@en .

av:contract a rdf:Property ;
    rdfs:label "contract"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Declared, accepted or actually used ResultContract identities. Each accepted declared output needs an exact contract pin in the dependency closure. Profile uses (alternative domains, not RDFS intersections): av:Need -> av:ResultContract [0..*]; av:Assignment -> av:ResultContract [0..*]; av:Result -> av:ResultContract [1..1]."@en .

av:coveragePolicy a rdf:Property ;
    rdfs:label "coveragePolicy"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Coverage obligation beginning at this queue stage through application delivery, separate from artifact/result completion state. Profile uses (alternative domains, not RDFS intersections): av:QueuePolicy -> enum:CoveragePolicy [1..1]."@en .

av:deliveredTracks a rdf:Property ;
    rdfs:label "deliveredTracks"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Hard application-delivery representation requirements. They do not describe tensors or inherit wire cadence as guaranteed delivered FPS. Profile uses (alternative domains, not RDFS intersections): av:InputAlternative -> av:TrackRequirement [1..*]."@en .

av:denominator a rdf:Property ;
    rdfs:label "denominator"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Strictly positive exact denominator, reduced with numerator by gcd. The same Rational shape is used everywhere. Profile uses (alternative domains, not RDFS intersections): av:Rational -> integer [1..1]."@en .

av:document a rdf:Property ;
    rdfs:label "document"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Explicit effective retrieval IRI for this exact representation. Distinct from Thing id, Form @id and href; preserve it as the base for native relative targets. Do not silently substitute redirects or latest versions. Profile uses (alternative domains, not RDFS intersections): av:DocumentPin -> IRI [1..1]."@en .

av:documentKind a rdf:Property ;
    rdfs:label "documentKind"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Exact provenance/content scope of pinned representation, especially publisher TD versus enriched directory snapshot. Profile uses (alternative domains, not RDFS intersections): av:DocumentPin -> enum:DocumentKind [1..1]."@en .

av:end a rdf:Property ;
    rdfs:label "end"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Exclusive rational end, strictly greater than start; absent for AtInstant. Bounds must lie within the selected finite extent. Fixed unit: second. Profile uses (alternative domains, not RDFS intersections): av:TimeSelector -> av:Rational [0..1]."@en .

av:evidence a rdf:Property ;
    rdfs:label "evidence"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Identified support for a claim/fault/timestamp; Result requires a pin of an authenticated durable receipt identifying result, payload digest, contract, run, checked grants and commit scope. Evidence identities are not self-authenticating. Profile uses (alternative domains, not RDFS intersections): av:Condition -> IRI [0..*]; av:Fault -> IRI [0..*]; av:Timestamp -> IRI [1..*]; av:Result -> av:DocumentPin [1..1]."@en .

av:expectedThing a rdf:Property ;
    rdfs:label "expectedThing"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Expected native TD id, required for any TD pin used by a FormReference. Anonymous legacy TDs need a separately identified and pinned named adapter snapshot. Profile uses (alternative domains, not RDFS intersections): av:DocumentPin -> td:Thing [0..1]."@en .

av:fence a rdf:Property ;
    rdfs:label "fence"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Monotonic ownership epoch within one authority/scope. Renewal preserves it; reassignment advances it. Do not compare unrelated scopes or assume a fence can recall an issued trigger. Profile uses (alternative domains, not RDFS intersections): av:LeaseGrant -> integer [1..1]."@en .

av:field a rdf:Property ;
    rdfs:label "field"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "The supported vocabulary property whose value is constrained. Unlisted fields/scripts/coercions are not a v0.1 matcher extension point. Profile uses (alternative domains, not RDFS intersections): av:IntegerConstraint -> enum:IntegerField [1..1]; av:RationalConstraint -> enum:RationalField [1..1]; av:ChoiceConstraint -> enum:ChoiceField [1..1]."@en .

av:form a rdf:Property ;
    rdfs:label "form"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Always the absolute @id of a native TD Form node, never its href. On InputAlternative this is an optional Processor sink Form; acceptance still uses FormReference. Profile uses (alternative domains, not RDFS intersections): av:Mode -> hctl:Form [1..1]; av:InputAlternative -> hctl:Form [0..1]; av:FormReference -> hctl:Form [1..1]."@en .

av:forms a rdf:Property ;
    rdfs:label "forms"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Accepted native interaction selections, including source and optional Processor sink legs. Each is a FormReference, not a duplicate target/transport/security object. Profile uses (alternative domains, not RDFS intersections): av:InputSelection -> av:FormReference [1..*]."@en .

av:frameRate a rdf:Property ;
    rdfs:label "frameRate"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Exact media cadence at the specified boundary: an offered Track states wire cadence; a TrackRequirement evaluates the wire or retained delivered samples as identified by its containing collection. Never infer delivered cadence from wire cadence after queue loss. This is not wall-clock decoder throughput; an arrival/deadline SLA must additionally fix clock/window semantics in a qualified delivery profile. 30000/1001 is not 30; faster-than-real-time clip processing does not alter media cadence. Fixed unit: frame/media-timeline-second. Profile uses (alternative domains, not RDFS intersections): av:Track -> av:Rational [0..1]."@en .

av:gapResponse a rdf:Property ;
    rdfs:label "gapResponse"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Failure/reporting obligation when coverage is incomplete; required for NoIntentionalDrop. Report never means complete success. Profile uses (alternative domains, not RDFS intersections): av:QueuePolicy -> enum:GapResponse [0..1]."@en .

av:generation a rdf:Property ;
    rdfs:label "generation"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Desired Need generation, repeated exactly by its Assignment and observation. Not a directory epoch, lease renewal sequence or fencing token. Profile uses (alternative domains, not RDFS intersections): av:Need -> integer [1..1]; av:Assignment -> integer [1..1]; av:AssignmentStatus -> integer [1..1]."@en .

av:goal a rdf:Property ;
    rdfs:label "goal"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "A delivered TrackRequirement goal named by dcterms:identifier, or source/backend/host ChoiceConstraint. Omitted tracks and unknown facts score false. Profile uses (alternative domains, not RDFS intersections): av:Preference -> ['av:TrackRequirement', 'av:ChoiceConstraint'] [1..1]."@en .

av:groups a rdf:Property ;
    rdfs:label "groups"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Disjoint all-or-none groups. A group containing a required member makes all members required; an all-optional group is admitted entirely or omitted. Profile uses (alternative domains, not RDFS intersections): av:Need -> av:InputGroup [0..*]."@en .

av:height a rdf:Property ;
    rdfs:label "height"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Actual display/image height in pixels, not sensor maximum or tensor height. Fixed unit: pixel. Profile uses (alternative domains, not RDFS intersections): av:Track -> integer [0..1]."@en .

av:hexDigest a rdf:Property ;
    rdfs:label "hexDigest"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Lowercase SHA-256 of the COMPLETE exact representation octets after HTTP content decoding, before parsing or media decoding; no whitespace normalization, field stripping, JCS or RDF canonicalization. Pin is external to covered document. Integrity is not authenticity. Profile uses (alternative domains, not RDFS intersections): av:DocumentPin -> string [1..1]."@en .

av:holder a rdf:Property ;
    rdfs:label "holder"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Authorized running processor/worker incarnation identity, not merely a service Thing or model file. Profile uses (alternative domains, not RDFS intersections): av:Assignment -> IRI [1..1]; av:LeaseGrant -> IRI [1..1]; av:ProcessingRun -> IRI [1..1]."@en .

av:host a rdf:Property ;
    rdfs:label "host"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Execution host identity, not device index or network address. HostLocal media Forms require it. Profile uses (alternative domains, not RDFS intersections): av:Connector -> IRI [1..1]; hctl:Form -> IRI [0..1]."@en .

av:incarnation a rdf:Property ;
    rdfs:label "incarnation"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Observer process or media stream incarnation defining sequence/timestamp scope. Restart/discontinuity requires a new identity; old sequences cannot overwrite current evidence. Profile uses (alternative domains, not RDFS intersections): av:AssignmentStatus -> IRI [1..1]; av:MediaSample -> IRI [0..1]."@en .

av:input a rdf:Property ;
    rdfs:label "input"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Named logical inputs of a Need/group or the input addressed by a preference. All group members belong to the same Need. Profile uses (alternative domains, not RDFS intersections): av:Need -> av:InputRequirement [1..*]; av:InputGroup -> av:InputRequirement [2..*]; av:Preference -> av:InputRequirement [1..1]."@en .

av:issues a rdf:Property ;
    rdfs:label "issues"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Explicit structured problems. A failed/degraded/draining cleanup or incomplete/error result cannot masquerade as successful empty output. Profile uses (alternative domains, not RDFS intersections): av:AssignmentStatus -> av:Fault [0..*]; av:ProcessingRun -> av:Fault [0..*]; av:Result -> av:Fault [0..*]."@en .

av:jsonPointer a rdf:Property ;
    rdfs:label "jsonPointer"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Optional RFC 6901 JSON Pointer evaluated against the pinned original JSON representation. If present, it must identify the same named native Form as av:form. Not an automatically supported URI fragment. Profile uses (alternative domains, not RDFS intersections): av:FormReference -> string [0..1]."@en .

av:kind a rdf:Property ;
    rdfs:label "kind"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Temporal media kind. Still does not imply fresh exposure; Clip requires a finite selector/extent. Profile uses (alternative domains, not RDFS intersections): av:Mode -> enum:MediaKind [1..1]; av:InputAlternative -> enum:MediaKind [1..1]; av:MediaAsset -> ['av:Still', 'av:Clip'] [1..1]."@en .

av:lease a rdf:Property ;
    rdfs:label "lease"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Externally enforced grant revisions: initial revisions on Assignment, observed currently applicable revisions on status, effect-checked revisions on a run. Renewals do not rewrite prior facts. Profile uses (alternative domains, not RDFS intersections): av:Assignment -> av:LeaseGrant [1..*]; av:AssignmentStatus -> av:LeaseGrant [1..*]; av:ProcessingRun -> av:LeaseGrant [1..*]."@en .

av:limitMs a rdf:Property ;
    rdfs:label "limitMs"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Maximum age/skew for TimingConstraint, or maximum residence at a QueuePolicy stage. Context fixes which bound; no implicit seconds conversion. Fixed unit: millisecond. Profile uses (alternative domains, not RDFS intersections): av:TimingConstraint -> number [1..1]; av:QueuePolicy -> number [0..1]."@en .

av:locality a rdf:Property ;
    rdfs:label "locality"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Access locality. Optional on generic Forms; exactly one is required for media Forms under native_form_rules. Profile uses (alternative domains, not RDFS intersections): hctl:Form -> enum:Locality [0..1]."@en .

av:lowerInteger a rdf:Property ;
    rdfs:label "lowerInteger"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Inclusive lower integer bound, in the fixed units of field. Profile uses (alternative domains, not RDFS intersections): av:IntegerConstraint -> integer [0..1]."@en .

av:lowerRational a rdf:Property ;
    rdfs:label "lowerRational"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Inclusive lower exact-rational bound, in the fixed units of field. Profile uses (alternative domains, not RDFS intersections): av:RationalConstraint -> av:Rational [0..1]."@en .

av:maxAge a rdf:Property ;
    rdfs:label "maxAge"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Hard worst-case media age at its explicit ApplicationIngress/InferenceStart stage, including all mapped clock uncertainty. Profile uses (alternative domains, not RDFS intersections): av:InputAlternative -> av:TimingConstraint [0..1]."@en .

av:maxSkew a rdf:Property ;
    rdfs:label "maxSkew"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Hard worst-case pairwise skew across included tracks or grouped inputs after proven common-domain conversion; compare video time to associated audio first-sample time. Profile uses (alternative domains, not RDFS intersections): av:InputAlternative -> av:TimingConstraint [0..1]; av:InputGroup -> av:TimingConstraint [0..1]."@en .

av:mediaDirection a rdf:Property ;
    rdfs:label "mediaDirection"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Media direction relative to the addressed Thing, not request/signaling/session-initiation direction. No universal Both value. Absent on control-only Forms; required for an unambiguously directed media access under native_form_rules. Profile uses (alternative domains, not RDFS intersections): hctl:Form -> enum:MediaDirection [0..1]."@en .

av:mode a rdf:Property ;
    rdfs:label "mode"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Links complete joint Modes, not independent capability axes. Profile uses (alternative domains, not RDFS intersections): av:Offer -> av:Mode [1..*]; av:InputSelection -> av:Mode [1..1]."@en .

av:model a rdf:Property ;
    rdfs:label "model"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Exact InferenceModel identity; its complete manifest/files/profiles are pinned independently of native TD/TM versions. Profile uses (alternative domains, not RDFS intersections): av:Need -> av:InferenceModel [0..1]; av:Assignment -> av:InferenceModel [0..1]."@en .

av:need a rdf:Property ;
    rdfs:label "need"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Links a described or accepted immutable Need revision, not its mutable head. Profile uses (alternative domains, not RDFS intersections): td:Thing -> av:Need [0..*]; av:Assignment -> av:Need [1..1]."@en .

av:numerator a rdf:Property ;
    rdfs:label "numerator"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Signed exact numerator; context requires positivity for rates/time bases and nonnegativity for selectors. Never n, tuple position zero or an anonymous mixed value. Profile uses (alternative domains, not RDFS intersections): av:Rational -> integer [1..1]."@en .

av:observedAt a rdf:Property ;
    rdfs:label "observedAt"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Timestamp when status was observed, with explicit timezone and observation clock. Record publication time may differ. Profile uses (alternative domains, not RDFS intersections): av:AssignmentStatus -> dateTime [1..1]."@en .

av:offer a rdf:Property ;
    rdfs:label "offer"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Links an advertised or selected Offer; no copied media address. Profile uses (alternative domains, not RDFS intersections): td:Thing -> av:Offer [0..*]; av:InputSelection -> av:Offer [1..1]."@en .

av:omitted a rdf:Property ;
    rdfs:label "omitted"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Explicit optional omissions, never missing required work. Assignment lists InputRequirement IDs; InputSelection lists omitted wire/delivered TrackRequirement IDs. Profile uses (alternative domains, not RDFS intersections): av:Assignment -> av:InputRequirement [0..*]; av:InputSelection -> av:TrackRequirement [0..*]."@en .

av:operation a rdf:Property ;
    rdfs:label "operation"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Exactly one existing native TD operation IRI. Resolve native op/defaults in the pinned Form/affordance and require compatibility; serialize native Form op using its standard lowercase TD token, never this AV property. Profile uses (alternative domains, not RDFS intersections): av:FormReference -> enum:NativeOperation [1..1]."@en .

av:overflow a rdf:Property ;
    rdfs:label "overflow"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Required reaction at capacity; BlockUpstream needs proven upstream support or bounded spool. Profile uses (alternative domains, not RDFS intersections): av:QueuePolicy -> enum:Overflow [1..1]."@en .

av:pin a rdf:Property ;
    rdfs:label "pin"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Exact fixed representations: FormReference has one TD pin; DocumentPin lists direct semantic/validation dependencies; Need/Assignment/status close over required records, contexts, profiles and artifacts; MediaAsset/InferenceModel/ResultContract have one recognized typed manifest; Result has its exact payload pin. Profile uses (alternative domains, not RDFS intersections): av:DocumentPin -> av:DocumentPin [0..*]; av:FormReference -> av:DocumentPin [1..1]; av:Need -> av:DocumentPin [0..*]; av:Assignment -> av:DocumentPin [1..*]; av:AssignmentStatus -> av:DocumentPin [0..*]; av:MediaAsset -> av:DocumentPin [1..1]; av:InferenceModel -> av:DocumentPin [1..1]; av:ResultContract -> av:DocumentPin [1..1]; av:Result -> av:DocumentPin [1..1]."@en .

av:pixelFormat a rdf:Property ;
    rdfs:label "pixelFormat"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Exact raw-pixel channel order/sample packing; colorimetry, strides and native PFNC mappings require qualified configuration. Profile uses (alternative domains, not RDFS intersections): av:Track -> enum:PixelFormat [0..1]."@en .

av:preferences a rdf:Property ;
    rdfs:label "preferences"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Lexicographically ordered Boolean goals; true before false. Rank only hard-feasible plans, then use stable input/source/mode/plan IDs as a deterministic tie-break. Profile uses (alternative domains, not RDFS intersections): av:Need -> av:Preference [0..*]."@en .

av:presence a rdf:Property ;
    rdfs:label "presence"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Admission obligation. Optional does not relax predicates after inclusion. Profile uses (alternative domains, not RDFS intersections): av:InputRequirement -> enum:Presence [1..1]; av:TrackRequirement -> enum:Presence [1..1]."@en .

av:processor a rdf:Property ;
    rdfs:label "processor"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Processing service Thing identity, not a loaded model or running instance. Profile uses (alternative domains, not RDFS intersections): av:Need -> av:Processor [1..1]; av:ProcessingRun -> av:Processor [0..1]."@en .

av:queues a rdf:Property ;
    rdfs:label "queues"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Explicit requested per-stage queue policies. The accepted qualified plan must disclose every queue, including internal buffers and pre-branch sharing, even if Need gives no bound. Profile uses (alternative domains, not RDFS intersections): av:InputAlternative -> av:QueuePolicy [0..*]."@en .

av:referenceClock a rdf:Property ;
    rdfs:label "referenceClock"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Target clock of a qualified bounded mapping. Presence requires matching configuration and uncertaintyMs; absence means no common-domain conversion is asserted. Profile uses (alternative domains, not RDFS intersections): av:TimestampMapping -> IRI [0..1]."@en .

av:representation a rdf:Property ;
    rdfs:label "representation"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "One exact encoded/raw representation family. On Track it is wire content; on TrackRequirement it describes the containing wire/delivered boundary. Profile uses (alternative domains, not RDFS intersections): av:Track -> enum:Representation [1..1]; av:TrackRequirement -> enum:Representation [1..1]."@en .

av:requirement a rdf:Property ;
    rdfs:label "requirement"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Requirement discharged by a selection. TrackSelection maps one offered track to one wire and/or one delivered requirement of the same logical name, never two from the same boundary. Wire-only filters are allowed; required coverage, optional omissions and boundary applicability are checked by admission. Profile uses (alternative domains, not RDFS intersections): av:InputSelection -> av:InputRequirement [1..1]; av:TrackSelection -> av:TrackRequirement [1..2]."@en .

av:resource a rdf:Property ;
    rdfs:label "resource"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "One named resource/fencing configuration domain, not an address. Profile uses (alternative domains, not RDFS intersections): av:ResourceUse -> IRI [1..1]."@en .

av:resourceUses a rdf:Property ;
    rdfs:label "resourceUses"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Complete shared resource/configuration uses of the Mode; admission also checks externally supplied capacities and allocations. Profile uses (alternative domains, not RDFS intersections): av:Mode -> av:ResourceUse [1..*]."@en .

av:sampleFormat a rdf:Property ;
    rdfs:label "sampleFormat"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "PCM numeric sample representation; separate from codec identity. Profile uses (alternative domains, not RDFS intersections): av:Track -> enum:SampleFormat [0..1]."@en .

av:sampleRate a rdf:Property ;
    rdfs:label "sampleRate"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Audio sampling frequency per channel; not bytes/second. Fixed unit: sample/second/channel. Profile uses (alternative domains, not RDFS intersections): av:Track -> integer [0..1]."@en .

av:scope a rdf:Property ;
    rdfs:label "scope"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "One authority-defined fencing/effect domain. Multi-scope assignments require independent current grants, not implied distributed atomicity. Profile uses (alternative domains, not RDFS intersections): av:LeaseGrant -> IRI [1..1]."@en .

av:selection a rdf:Property ;
    rdfs:label "selection"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Exact selector edge/sample semantics. No implied frame-index/FPS conversion, URI fragment support or clip-generation command. Profile uses (alternative domains, not RDFS intersections): av:TimeSelector -> enum:SelectorKind [1..1]."@en .

av:selections a rdf:Property ;
    rdfs:label "selections"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Accepted mappings: Assignment has InputSelections; each InputSelection has TrackSelections for all included logical tracks. Profile uses (alternative domains, not RDFS intersections): av:Assignment -> av:InputSelection [1..*]; av:InputSelection -> av:TrackSelection [1..*]."@en .

av:selector a rdf:Property ;
    rdfs:label "selector"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Full offered Clip extent on Mode, requested selection on an alternative, or retained/selected-media extent. All values use one named timeline; seeking ability comes only from a recognized configuration. Profile uses (alternative domains, not RDFS intersections): av:Mode -> av:TimeSelector [0..1]; av:InputAlternative -> av:TimeSelector [0..1]; av:MediaAsset -> av:TimeSelector [0..1]; av:MediaSample -> av:TimeSelector [0..1]."@en .

av:sequence a rdf:Property ;
    rdfs:label "sequence"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Nonnegative ordinal within its explicit scope: observer-incarnation/Assignment observations, stream media units, or lease-series renewals. Not a global cursor, packet sequence or fencing token. Profile uses (alternative domains, not RDFS intersections): av:AssignmentStatus -> integer [1..1]; av:MediaSample -> integer [0..1]; av:LeaseGrant -> integer [1..1]."@en .

av:sharing a rdf:Property ;
    rdfs:label "sharing"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Resource sharing requires exact complete-configuration equivalence, not overlapping parameter subsets or similarly named IDs. Profile uses (alternative domains, not RDFS intersections): av:ResourceUse -> enum:Sharing [1..1]."@en .

av:source a rdf:Property ;
    rdfs:label "source"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Media source identity; omission on an alternative permits discovery. Profile uses (alternative domains, not RDFS intersections): av:Offer -> av:MediaSource [1..1]; av:InputAlternative -> av:MediaSource [0..1]; av:MediaSample -> av:MediaSource [0..1]."@en .

av:stage a rdf:Property ;
    rdfs:label "stage"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Queue boundary or age-evaluation boundary. Not a global drop switch. Profile uses (alternative domains, not RDFS intersections): av:QueuePolicy -> ['av:CaptureIngress', 'av:EncodedBranch', 'av:DecodedDelivery', 'av:ModelInput'] [1..1]; av:TimingConstraint -> ['av:ApplicationIngress', 'av:InferenceStart'] [0..1]."@en .

av:start a rdf:Property ;
    rdfs:label "start"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Nonnegative rational start/instant from selector clock origin. Fixed unit: second. Profile uses (alternative domains, not RDFS intersections): av:TimeSelector -> av:Rational [1..1]."@en .

av:state a rdf:Property ;
    rdfs:label "state"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Class-specific lifecycle or content state, always an IRI. No direct inference to Condition truth or currentness follows from it. Profile uses (alternative domains, not RDFS intersections): av:Need -> enum:NeedState [1..1]; av:AssignmentStatus -> enum:AssignmentState [1..1]; av:ProcessingRun -> enum:RunState [1..1]; av:MediaAsset -> ['av:Complete', 'av:Partial'] [1..1]; av:Result -> enum:ContentState [1..1]."@en .

av:time a rdf:Property ;
    rdfs:label "time"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Exact observed rational seconds from the stated clock origin. Raw tick/UTC affine conversion and exposure provenance must be retained as evidence; not a datetime-or-integer union. Fixed unit: second. Profile uses (alternative domains, not RDFS intersections): av:Timestamp -> av:Rational [1..1]."@en .

av:timeBase a rdf:Property ;
    rdfs:label "timeBase"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Exact source tick duration; numerator is positive. Mapping configuration fixes affine offset, anchor, bounded tick intervals, drift uncertainty and resets. Fixed unit: second/tick. Profile uses (alternative domains, not RDFS intersections): av:TimestampMapping -> av:Rational [1..1]."@en .

av:timing a rdf:Property ;
    rdfs:label "timing"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Track mapping descriptions or actual sample timestamps. A description of mapping capability is not observed timing evidence. Profile uses (alternative domains, not RDFS intersections): av:Track -> av:TimestampMapping [0..*]; av:MediaSample -> av:Timestamp [0..*]."@en .

av:toleranceMs a rdf:Property ;
    rdfs:label "toleranceMs"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Maximum permitted excess at each CoveringInterval edge; required only for that selector kind. Fixed unit: millisecond. Profile uses (alternative domains, not RDFS intersections): av:TimeSelector -> number [0..1]."@en .

av:track a rdf:Property ;
    rdfs:label "track"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Links offered media Track identities. A TrackRequirement may optionally restrict selection to one exact Track. Profile uses (alternative domains, not RDFS intersections): av:Mode -> av:Track [1..*]; av:TrackRequirement -> av:Track [0..1]; av:TrackSelection -> av:Track [1..1]; av:MediaSample -> av:Track [0..1]."@en .

av:transformPermissions a rdf:Property ;
    rdfs:label "transformPermissions"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Explicit operations permitted between wire and delivered media. Omitted/empty permits none; queue discards and model preprocessing are governed separately. Profile uses (alternative domains, not RDFS intersections): av:InputAlternative -> enum:Transform [0..*]."@en .

av:uncertaintyMs a rdf:Property ;
    rdfs:label "uncertaintyMs"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Conservative error bound. Omission means unknown, not zero; mapping scope/validity must be proved by pinned records. Fixed unit: millisecond. Profile uses (alternative domains, not RDFS intersections): av:TimestampMapping -> number [0..1]; av:Timestamp -> number [0..1]; av:AssignmentStatus -> number [0..1]; av:LeaseGrant -> number [0..1]."@en .

av:unit a rdf:Property ;
    rdfs:label "unit"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Queue capacity unit. Fixed-unit physical terms do not take an arbitrary unit field. Profile uses (alternative domains, not RDFS intersections): av:QueuePolicy -> enum:QueueUnit [1..1]."@en .

av:upperInteger a rdf:Property ;
    rdfs:label "upperInteger"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Inclusive upper integer bound, in the fixed units of field; must not be below lowerInteger. Profile uses (alternative domains, not RDFS intersections): av:IntegerConstraint -> integer [0..1]."@en .

av:upperRational a rdf:Property ;
    rdfs:label "upperRational"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Inclusive upper exact-rational bound, in the fixed units of field; compare to lowerRational by exact cross multiplication. Profile uses (alternative domains, not RDFS intersections): av:RationalConstraint -> av:Rational [0..1]."@en .

av:validFrom a rdf:Property ;
    rdfs:label "validFrom"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Inclusive grant start on the authority's named, uncertainty-bounded clock. Profile uses (alternative domains, not RDFS intersections): av:LeaseGrant -> dateTime [1..1]."@en .

av:validUntil a rdf:Property ;
    rdfs:label "validUntil"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/lifecycle> ;
    rdfs:comment "Exclusive freshness/expiry boundary. Status uses [observedAt,validUntil); grant uses [validFrom,validUntil), subject to earlier revocation. Profile uses (alternative domains, not RDFS intersections): av:AssignmentStatus -> dateTime [1..1]; av:LeaseGrant -> dateTime [1..1]."@en .

av:width a rdf:Property ;
    rdfs:label "width"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Actual display/image width in pixels, not sensor maximum, byte stride or tensor width. Fixed unit: pixel. Profile uses (alternative domains, not RDFS intersections): av:Track -> integer [0..1]."@en .

av:wireTracks a rdf:Property ;
    rdfs:label "wireTracks"@en ;
    dcterms:isPartOf <https://example.org/wot/av/module/core> ;
    rdfs:comment "Additional hard constraints at the negotiated source wire boundary, before decode/conversion/queue loss. Logical track names join to deliveredTracks. Profile uses (alternative domains, not RDFS intersections): av:InputAlternative -> av:TrackRequirement [0..*]."@en .

documents.https://example.org/wot/av/shapes/v0.1.t:
# GENERATED from wot-av-formal-v0.1.terms.json and structural rules in .build.py.
# Original proposal; namespace and context placeholders are unregistered/unhosted.
# Structural subset only. No SHACL engine or full SHACL syntax validator was run.
# Named external references require separate resolution; list traversal does not prove list topology.

@prefix av: <https://example.org/wot/av#> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix prov: <http://www.w3.org/ns/prov#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix td: <https://www.w3.org/2019/wot/td#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

av:AssignmentShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. An immutable accepted mapping of one Need revision to selected input/track paths and initial grants. Not a WoT protocol binding or an execution Activity."@en ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:need ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:model ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:contract ],
        [ sh:datatype xsd:integer ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:minInclusive 0 ;
            sh:path av:generation ],
        [ sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:pin ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:holder ],
        [ sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:selections ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:omitted ],
        [ sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:lease ],
        [ sh:datatype xsd:string ;
            sh:minCount 0 ;
            sh:path dcterms:description ],
        [ sh:datatype xsd:string ;
            sh:minCount 0 ;
            sh:path dcterms:title ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:creator ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:publisher ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:license ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:references ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path prov:wasAttributedTo ] ;
    sh:targetClass av:Assignment .

av:AssignmentStatusShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. An immutable observation of an Assignment at a generation and observer-incarnation sequence. Currentness, revocation and head selection must be checked externally."@en ;
    sh:and ( [ a sh:NodeShape ;
                sh:or ( [ a sh:NodeShape ;
                            sh:not [ a sh:NodeShape ;
                                    sh:property [ sh:hasValue av:Ready ;
                                            sh:path av:state ] ] ] [ a sh:NodeShape ;
                            sh:property [ sh:path av:conditions ;
                                    sh:qualifiedMinCount 1 ;
                                    sh:qualifiedValueShape [ a sh:NodeShape ;
                                            sh:property [ sh:hasValue av:ApplicationReady ;
                                                    sh:path av:condition ],
                                                [ sh:hasValue av:True ;
                                                    sh:path av:conditionState ] ] ] ] ) ] ) ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:datatype xsd:integer ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:minInclusive 0 ;
            sh:path av:generation ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:clock ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:minInclusive 0 ;
            sh:or ( [ a sh:NodeShape ;
                        sh:datatype xsd:integer ] [ a sh:NodeShape ;
                        sh:datatype xsd:decimal ] [ a sh:NodeShape ;
                        sh:datatype xsd:double ] ) ;
            sh:path av:uncertaintyMs ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:pin ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:assignment ],
        [ sh:in ( av:Accepted av:Applying av:Ready av:Degraded av:Failed av:Draining av:Released ) ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:state ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:incarnation ],
        [ sh:datatype xsd:integer ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:minInclusive 0 ;
            sh:path av:sequence ],
        [ sh:datatype xsd:dateTime ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:path av:observedAt ],
        [ sh:datatype xsd:dateTime ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:path av:validUntil ],
        [ sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:lease ],
        [ sh:maxCount 4 ;
            sh:minCount 4 ;
            sh:node av:ConditionShape ;
            sh:nodeKind sh:BlankNodeOrIRI ;
            sh:path av:conditions ],
        [ sh:minCount 0 ;
            sh:node av:FaultShape ;
            sh:nodeKind sh:BlankNodeOrIRI ;
            sh:path av:issues ],
        [ sh:datatype xsd:string ;
            sh:minCount 0 ;
            sh:path dcterms:description ],
        [ sh:datatype xsd:string ;
            sh:minCount 0 ;
            sh:path dcterms:title ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:creator ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:publisher ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:license ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:references ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path prov:wasAttributedTo ],
        [ sh:lessThan av:validUntil ;
            sh:path av:observedAt ],
        [ sh:path av:conditions ;
            sh:qualifiedMaxCount 1 ;
            sh:qualifiedMinCount 1 ;
            sh:qualifiedValueShape [ a sh:NodeShape ;
                    sh:property [ sh:hasValue av:MediaObserved ;
                            sh:path av:condition ] ] ],
        [ sh:path av:conditions ;
            sh:qualifiedMaxCount 1 ;
            sh:qualifiedMinCount 1 ;
            sh:qualifiedValueShape [ a sh:NodeShape ;
                    sh:property [ sh:hasValue av:ApplicationReady ;
                            sh:path av:condition ] ] ],
        [ sh:path av:conditions ;
            sh:qualifiedMaxCount 1 ;
            sh:qualifiedMinCount 1 ;
            sh:qualifiedValueShape [ a sh:NodeShape ;
                    sh:property [ sh:hasValue av:ModelLoaded ;
                            sh:path av:condition ] ] ],
        [ sh:path av:conditions ;
            sh:qualifiedMaxCount 1 ;
            sh:qualifiedMinCount 1 ;
            sh:qualifiedValueShape [ a sh:NodeShape ;
                    sh:property [ sh:hasValue av:ResultCommitted ;
                            sh:path av:condition ] ] ] ;
    sh:targetClass av:AssignmentStatus .

av:ConnectorShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. A Thing exposing acquisition or adaptation, including host-local native camera access. Not automatically a sensor or PROV Agent."@en ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:offer ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:need ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:host ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:backend ] ;
    sh:targetClass av:Connector .

av:ControllerShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. A Thing exposing coordination interactions through native TD affordances. Its metadata does not implement admission or authority."@en ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:offer ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:need ] ;
    sh:targetClass av:Controller .

av:DocumentPinShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. A fixed representation snapshot with retrieval location, exact-octet SHA-256 and provenance scope. dcterms:format/conformsTo describe the pinned content, not the JSON serialization of this descriptive pin record."@en ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:document ],
        [ sh:in ( av:PublisherTD av:DirectorySnapshot av:ContextDocument av:OntologyDocument av:ShapeDocument av:ProfileDocument av:DomainDocument av:ManifestDocument av:PayloadDocument av:ReceiptDocument av:ArtifactFile ) ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:documentKind ],
        [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:path av:hexDigest ;
            sh:pattern "^[0-9a-f]{64}$" ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:pin ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:expectedThing ],
        [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:path dcterms:format ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:conformsTo ],
        [ sh:datatype xsd:string ;
            sh:minCount 0 ;
            sh:path dcterms:description ],
        [ sh:datatype xsd:string ;
            sh:minCount 0 ;
            sh:path dcterms:title ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:creator ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:publisher ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:license ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:references ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path prov:wasAttributedTo ] ;
    sh:targetClass av:DocumentPin .

av:InferenceModelShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. A versioned learned-model manifest with verified files, exact tensor/pre/postprocessing/runtime semantics. Neither a WoT Thing Model, JSON Schema, nor xRegistry model."@en ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:pin ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:isVersionOf ],
        [ sh:datatype xsd:string ;
            sh:minCount 0 ;
            sh:path dcterms:description ],
        [ sh:datatype xsd:string ;
            sh:minCount 0 ;
            sh:path dcterms:title ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:creator ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:publisher ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:license ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:references ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path prov:wasGeneratedBy ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path prov:wasDerivedFrom ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path prov:wasAttributedTo ] ;
    sh:targetClass av:InferenceModel .

av:InputAlternativeShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. One complete permitted input contract. Its predicates are conjunctive; alternatives are disjunctive, without array-order priority."@en ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:source ],
        [ sh:in ( av:Live av:Still av:Clip ) ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:kind ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:form ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:wireTracks ],
        [ sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:deliveredTracks ],
        [ sh:minCount 0 ;
            sh:node av:ChoiceConstraintShape ;
            sh:nodeKind sh:BlankNodeOrIRI ;
            sh:path av:constraints ],
        [ sh:in ( av:Observe av:RequestCapture av:ConfigureAndCapture ) ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:captureIntent ],
        [ sh:in ( av:Decode av:ColorConvert av:ResizeStretch av:ResizeCrop av:ResizeLetterbox av:ResampleAudio av:RemixAudio av:TemporalSubsample av:DuplicateFrames av:PrerollDecode ) ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:transformPermissions ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:node av:TimeSelectorShape ;
            sh:nodeKind sh:BlankNodeOrIRI ;
            sh:path av:selector ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:node av:TimingConstraintShape ;
            sh:nodeKind sh:BlankNodeOrIRI ;
            sh:path av:maxAge ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:node av:TimingConstraintShape ;
            sh:nodeKind sh:BlankNodeOrIRI ;
            sh:path av:maxSkew ],
        [ sh:minCount 0 ;
            sh:node av:QueuePolicyShape ;
            sh:nodeKind sh:BlankNodeOrIRI ;
            sh:path av:queues ] ;
    sh:targetClass av:InputAlternative .

av:InputGroupShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. An all-or-none group of at least two Need inputs, optionally synchronized. Groups are disjoint in v0.1; admission atomicity is not physical transaction atomicity."@en ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:minCount 2 ;
            sh:nodeKind sh:IRI ;
            sh:path av:input ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:node av:TimingConstraintShape ;
            sh:nodeKind sh:BlankNodeOrIRI ;
            sh:path av:maxSkew ] ;
    sh:targetClass av:InputGroup .

av:InputRequirementShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. One named logical workload input, required or optional, with complete alternatives. A Need may have multiple such inputs."@en ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:in ( av:Required av:Optional ) ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:presence ],
        [ sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:alternative ],
        [ sh:datatype xsd:string ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:path dcterms:identifier ] ;
    sh:targetClass av:InputRequirement .

av:InputSelectionShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. One accepted logical input, complete alternative, Offer, Mode, adapter configuration and source/sink native Form selections."@en ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:offer ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:mode ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:configuration ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:alternative ],
        [ sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:selections ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:omitted ],
        [ sh:minCount 1 ;
            sh:node av:FormReferenceShape ;
            sh:nodeKind sh:BlankNodeOrIRI ;
            sh:path av:forms ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:requirement ] ;
    sh:targetClass av:InputSelection .

av:LeaseGrantShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. An immutable revision of an externally enforced, single-authority/scope grant. dcterms:isVersionOf is its series; renewal sequence and fencing epoch are distinct."@en ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:clock ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:minInclusive 0 ;
            sh:or ( [ a sh:NodeShape ;
                        sh:datatype xsd:integer ] [ a sh:NodeShape ;
                        sh:datatype xsd:decimal ] [ a sh:NodeShape ;
                        sh:datatype xsd:double ] ) ;
            sh:path av:uncertaintyMs ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:holder ],
        [ sh:datatype xsd:integer ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:minInclusive 0 ;
            sh:path av:sequence ],
        [ sh:datatype xsd:dateTime ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:path av:validFrom ],
        [ sh:datatype xsd:dateTime ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:path av:validUntil ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:authority ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:scope ],
        [ sh:datatype xsd:integer ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:minInclusive 0 ;
            sh:path av:fence ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:isVersionOf ],
        [ sh:datatype xsd:string ;
            sh:minCount 0 ;
            sh:path dcterms:description ],
        [ sh:datatype xsd:string ;
            sh:minCount 0 ;
            sh:path dcterms:title ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:creator ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:publisher ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:license ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:references ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path prov:wasAttributedTo ],
        [ sh:lessThan av:validUntil ;
            sh:path av:validFrom ] ;
    sh:targetClass av:LeaseGrant .

av:MediaAssetShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. Sealed retained still or clip content, complete or explicitly partial, described by an exact typed manifest. Not its Offer or storage endpoint."@en ;
    sh:and ( [ a sh:NodeShape ;
                sh:or ( [ a sh:NodeShape ;
                            sh:not [ a sh:NodeShape ;
                                    sh:property [ sh:hasValue av:Clip ;
                                            sh:path av:kind ] ] ] [ a sh:NodeShape ;
                            sh:property [ sh:maxCount 1 ;
                                    sh:minCount 1 ;
                                    sh:path av:selector ] ] ) ] [ a sh:NodeShape ;
                sh:or ( [ a sh:NodeShape ;
                            sh:not [ a sh:NodeShape ;
                                    sh:property [ sh:hasValue av:Still ;
                                            sh:path av:kind ] ] ] [ a sh:NodeShape ;
                            sh:property [ sh:hasValue av:Complete ;
                                    sh:path av:state ] ] ) ] ) ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:in ( av:Still av:Clip ) ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:kind ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:node av:TimeSelectorShape ;
            sh:nodeKind sh:BlankNodeOrIRI ;
            sh:path av:selector ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:pin ],
        [ sh:in ( av:Complete av:Partial ) ;
            sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:nodeKind sh:IRI ;
            sh:path av:state ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:isVersionOf ],
        [ sh:datatype xsd:string ;
            sh:minCount 0 ;
            sh:path dcterms:description ],
        [ sh:datatype xsd:string ;
            sh:minCount 0 ;
            sh:path dcterms:title ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:creator ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:publisher ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:license ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path dcterms:references ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path prov:wasGeneratedBy ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path prov:wasDerivedFrom ],
        [ sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path prov:wasAttributedTo ] ;
    sh:targetClass av:MediaAsset .

av:MediaFormShape a sh:NodeShape ;
    sh:and ( [ a sh:NodeShape ;
                sh:or ( [ a sh:NodeShape ;
                            sh:not [ a sh:NodeShape ;
                                    sh:property [ sh:hasValue av:HostLocal ;
                                            sh:path av:locality ] ] ] [ a sh:NodeShape ;
                            sh:property [ sh:maxCount 1 ;
                                    sh:minCount 1 ;
                                    sh:path av:host ] ] ) ] ) ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:host ],
        [ sh:in ( av:HostLocal av:Network ) ;
            sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:locality ],
        [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:binding ],
        [ sh:in ( av:ToThing av:FromThing ) ;
            sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:mediaDirection ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:path av:mediaDirection ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:path av:locality ],
        [ sh:maxCount 1 ;
            sh:minCount 1 ;
            sh:path av:binding ] ;
    sh:targetSubjectsOf av:mediaDirection .

av:MediaSampleShape a sh:NodeShape ;
    rdfs:comment "Structural subset only. A selected media unit: either derived from a retained asset with a selector, or identified by source, stream incarnation, Track and media-unit sequence. It need not have a media URL."@en ;
    sh:nodeKind sh:IRI ;
    sh:property [ sh:maxCount 1 ;
            sh:minCount 0 ;
            sh:nodeKind sh:IRI ;
            sh:path av:source ],
        [ sh:maxCount 1 ;
